import { useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import logo from "../assets/logo.jpg";

export default function Navbar() {
  const [open, setOpen] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();

  const goToSection = (id) => {
    setOpen(false);

    if (location.pathname !== "/") {
      navigate(`/#${id}`);
      return;
    }

    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: "smooth" });
  };

  return (
    <nav className="fixed top-0 w-full z-50 bg-black/80 backdrop-blur border-b border-white/10">
      <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
        {/* LOGO */}
        <img
          src={logo}
          alt="BodyZeal Fitworks"
          className="h-12 cursor-pointer"
          onClick={() => navigate("/")}
        />

        {/* DESKTOP */}
        <ul className="hidden md:flex gap-8 text-white font-medium">
          <li onClick={() => goToSection("hero")} className="nav-item">
            Home
          </li>
          <li
            onClick={() => goToSection("training-videos")}
            className="nav-item"
          >
            Videos
          </li>
          <li className="nav-item">
            <Link to="/gallery">Gallery</Link>
          </li>
          <li className="nav-item">
            <Link to="/testimonials">Testimonials</Link>
          </li>
        </ul>

        {/* MOBILE BUTTON */}
        <button
          className="md:hidden text-white text-3xl"
          onClick={() => setOpen(!open)}
        >
          ☰
        </button>
      </div>

      {/* MOBILE MENU */}
      {open && (
        <div className="md:hidden bg-black border-t border-white/10 px-6 py-6 space-y-4 text-white">
          <p onClick={() => goToSection("hero")} className="nav-item">
            Home
          </p>
          <p
            onClick={() => goToSection("training-videos")}
            className="nav-item"
          >
            Videos
          </p>
          <Link onClick={() => setOpen(false)} to="/gallery" className="nav-item block">
            Gallery
          </Link>
          <Link
            onClick={() => setOpen(false)}
            to="/testimonials"
            className="nav-item block"
          >
            Testimonials
          </Link>
        </div>
      )}
    </nav>
  );
}
